    pr=propsAtTR(T,got.rho);
    if(!pr.ok||!(pr.cp>100))return{T:NaN,rho:NaN,u:NaN,h:NaN,cp:NaN,ok:false};
    const dT=(s-pr.s)*T/pr.cp;
